"""Microsoft Entra authentication for Azure AI Foundry benchmark calls."""

from __future__ import annotations

import asyncio
import os
import threading
from collections.abc import AsyncGenerator, Callable

import httpx
import requests

FOUNDRY_SCOPE = "https://cognitiveservices.azure.com/.default"
GITHUB_OIDC_AUDIENCE = "api://AzureADTokenExchange"


def _required_env(name: str) -> str:
    value = os.getenv(name)
    if not value:
        raise RuntimeError(f"{name} is required for GitHub OIDC authentication")
    return value


def _github_oidc_assertion() -> str:
    """Request a fresh GitHub OIDC assertion for Azure workload federation."""
    response = requests.get(
        _required_env("ACTIONS_ID_TOKEN_REQUEST_URL"),
        headers={
            "Authorization": f"bearer {_required_env('ACTIONS_ID_TOKEN_REQUEST_TOKEN')}"
        },
        params={"audience": GITHUB_OIDC_AUDIENCE},
        timeout=10,
    )
    response.raise_for_status()
    assertion = response.json().get("value")
    if not isinstance(assertion, str) or not assertion:
        raise RuntimeError("GitHub OIDC response did not contain a non-empty value")
    return assertion


def _build_token_provider() -> Callable[[], str]:
    """Build a caching Entra token provider for CI or local keyless auth."""
    from azure.identity import (
        ClientAssertionCredential,
        DefaultAzureCredential,
        get_bearer_token_provider,
    )

    oidc_url = os.getenv("ACTIONS_ID_TOKEN_REQUEST_URL")
    oidc_request_token = os.getenv("ACTIONS_ID_TOKEN_REQUEST_TOKEN")
    if bool(oidc_url) != bool(oidc_request_token):
        raise RuntimeError(
            "ACTIONS_ID_TOKEN_REQUEST_URL and ACTIONS_ID_TOKEN_REQUEST_TOKEN "
            "must either both be set or both be absent"
        )

    if oidc_url:
        credential = ClientAssertionCredential(
            tenant_id=_required_env("AZURE_TENANT_ID"),
            client_id=_required_env("AZURE_CLIENT_ID"),
            func=_github_oidc_assertion,
        )
    else:
        credential = DefaultAzureCredential()

    return get_bearer_token_provider(credential, FOUNDRY_SCOPE)


class EntraBearerAuth(httpx.Auth):
    """Replace any SDK placeholder auth with a fresh Entra bearer token."""

    def __init__(self, token_provider: Callable[[], str] | None = None) -> None:
        self._token_provider = token_provider or _build_token_provider()
        self._provider_lock = threading.Lock()

    def _get_token(self) -> str:
        # Azure Identity caches and proactively refreshes the access token. The
        # lock prevents a concurrent first request/refresh from causing a burst
        # of identical assertion exchanges.
        with self._provider_lock:
            return self._token_provider()

    async def async_auth_flow(
        self, request: httpx.Request
    ) -> AsyncGenerator[httpx.Request, httpx.Response]:
        token = await asyncio.to_thread(self._get_token)
        request.headers.pop("api-key", None)
        request.headers["Authorization"] = f"Bearer {token}"
        yield request


def build_entra_auth() -> httpx.Auth:
    """Return HTTPX auth backed by an automatically refreshing Entra token."""
    return EntraBearerAuth()
"""Tests for refreshable Microsoft Entra authentication."""

from __future__ import annotations

import asyncio
import os
import unittest
from unittest.mock import Mock, patch

import httpx

from benchmarks.common import entra_auth


class EntraBearerAuthTests(unittest.TestCase):
    def test_auth_replaces_api_key_and_placeholder_bearer_each_request(self) -> None:
        tokens = iter(("first-token", "refreshed-token"))
        seen_headers: list[httpx.Headers] = []

        async def exercise() -> None:
            def handle(request: httpx.Request) -> httpx.Response:
                seen_headers.append(request.headers)
                return httpx.Response(200, json={"ok": True})

            async with httpx.AsyncClient(
                auth=entra_auth.EntraBearerAuth(lambda: next(tokens)),
                transport=httpx.MockTransport(handle),
            ) as client:
                for _ in range(2):
                    response = await client.get(
                        "https://example.test/models/chat/completions",
                        headers={
                            "Authorization": "Bearer sdk-placeholder",
                            "api-key": "must-not-leak",
                        },
                    )
                    self.assertEqual(response.status_code, 200)

        asyncio.run(exercise())
        self.assertEqual(
            [headers["Authorization"] for headers in seen_headers],
            ["Bearer first-token", "Bearer refreshed-token"],
        )
        self.assertTrue(all("api-key" not in headers for headers in seen_headers))

    @patch.dict(
        os.environ,
        {
            "ACTIONS_ID_TOKEN_REQUEST_URL": "https://github.test/oidc?api-version=1",
            "ACTIONS_ID_TOKEN_REQUEST_TOKEN": "runner-request-token",
        },
        clear=True,
    )
    @patch("benchmarks.common.entra_auth.requests.get")
    def test_github_assertion_requests_azure_audience(self, get: Mock) -> None:
        get.return_value.json.return_value = {"value": "fresh-assertion"}

        assertion = entra_auth._github_oidc_assertion()

        self.assertEqual(assertion, "fresh-assertion")
        get.assert_called_once_with(
            "https://github.test/oidc?api-version=1",
            headers={"Authorization": "bearer runner-request-token"},
            params={"audience": "api://AzureADTokenExchange"},
            timeout=10,
        )
        get.return_value.raise_for_status.assert_called_once_with()

    @patch.dict(
        os.environ,
        {
            "ACTIONS_ID_TOKEN_REQUEST_URL": "https://github.test/oidc",
            "ACTIONS_ID_TOKEN_REQUEST_TOKEN": "runner-request-token",
            "AZURE_TENANT_ID": "tenant-id",
            "AZURE_CLIENT_ID": "client-id",
        },
        clear=True,
    )
    @patch("azure.identity.get_bearer_token_provider")
    @patch("azure.identity.ClientAssertionCredential")
    def test_ci_uses_refreshable_client_assertion_credential(
        self, credential: Mock, bearer_provider: Mock
    ) -> None:
        provider = Mock(return_value="access-token")
        bearer_provider.return_value = provider

        result = entra_auth._build_token_provider()

        self.assertIs(result, provider)
        credential.assert_called_once_with(
            tenant_id="tenant-id",
            client_id="client-id",
            func=entra_auth._github_oidc_assertion,
        )
        bearer_provider.assert_called_once_with(
            credential.return_value, entra_auth.FOUNDRY_SCOPE
        )

    @patch.dict(os.environ, {}, clear=True)
    @patch("azure.identity.get_bearer_token_provider")
    @patch("azure.identity.DefaultAzureCredential")
    def test_local_run_uses_default_azure_credential(
        self, credential: Mock, bearer_provider: Mock
    ) -> None:
        provider = Mock(return_value="access-token")
        bearer_provider.return_value = provider

        result = entra_auth._build_token_provider()

        self.assertIs(result, provider)
        credential.assert_called_once_with()
        bearer_provider.assert_called_once_with(
